// Deep Sleep — wake up by timer
#include <esp_sleep.h>

#define uS_TO_S 1000000ULL
int sleepSeconds = 10;

void setup() {
  Serial.begin(115200);
  delay(1000);

  Serial.printf("Awake! Reason: %d\n", esp_sleep_get_wakeup_cause());

  // Print wakeup reason
  switch (esp_sleep_get_wakeup_cause()){
    case ESP_SLEEP_WAKEUP_TIMER:
      Serial.println("Woke by timer"); break;
    default:
      Serial.println("Power-on reset"); break;
  }

  // Deep sleep
  Serial.printf("Sleeping for %d s\n", sleepSeconds);
  esp_sleep_enable_timer_wakeup(sleepSeconds * uS_TO_S);
  esp_deep_sleep_start();
}

void loop() {}
